UPDATE articles SET
  title = '여행업계, 2025년 세계 관광객 14억 명 추산…2019년의 99% 회복',
  slug = 'global-tourism-2024-nears-pre-pandemic-level',
  summary = 'UN Tourism의 2025년 1월 발표를 바탕으로 세계 관광 회복세와 지역별 격차를 살펴봅니다.',
  content = '## 세계 관광 회복, 지역별 속도는 달랐다\n\nUN Tourism은 2025년 1월 발표에서 2024년 국제 관광객을 약 14억 명으로 추산했습니다. 전년보다 11% 늘어 2019년의 약 99%에 도달한 수치입니다.\n\n유럽은 7억4,700만 명으로 2019년보다 1% 많았지만, 아시아·태평양은 팬데믹 이전 수준의 87%였습니다. 총량의 회복과 지역별 격차를 함께 볼 필요가 있습니다.\n\n> 기준: 2024년 잠정 추산, 발표일: 2025-01-20.\n\n[자료: UN Tourism - International tourism recovers pre-pandemic levels in 2024](https://www.untourism.int/news/international-tourism-recovers-pre-pandemic-levels-in-2024)',
  category = 'major',
  author = '체크인데일리 편집팀',
  cover_image = 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80',
  status = 'published',
  published_at = '2025-01-20T03:00:00.000Z',
  updated_at = '2026-10-08T00:00:00.000Z'
WHERE id = 3;

UPDATE articles SET
  title = '에어아시아, 2025년 신규 노선 30개 이상 추진…다윈 노선도 발표',
  slug = 'airasia-2025-new-routes-darwin',
  summary = '에어아시아 그룹의 노선 확장 계획과 쿠알라룸푸르-다윈 연결 계획을 발표 당시 자료로 정리했습니다.',
  content = '## 동남아 노선망 확장 계획\n\n에어아시아 그룹은 2025년 신규 노선 30개 이상을 추진한다고 발표했습니다. 에어아시아 말레이시아는 쿠알라룸푸르-다윈 노선을 주 4회 운항하고 2025년 6월 27일 시작할 계획이라고 밝혔습니다.\n\n당시 회사는 항공기 16대 재가동과 14대 신규 인도 계획도 공개했습니다. 아래 내용은 회사의 2025년 계획·발표 기준이며, 현재 운항 일정은 항공사에서 다시 확인해야 합니다.\n\n[자료: AirAsia Newsroom, 2025-03-25](https://newsroom.airasia.com/news/airasia-expects-to-launch-over-30-new-routes-in-2025-boosting-regional-and-fly-thru-connectivity)',
  author = '체크인데일리 편집팀',
  cover_image = 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80',
  status = 'published',
  published_at = '2025-03-25T03:00:00.000Z',
  updated_at = '2026-10-08T00:00:00.000Z'
WHERE id = 1;

UPDATE articles SET
  title = '삿포로에 홋카이도 첫 Hyatt Centric 개장…객실 216실',
  slug = 'hyatt-centric-sapporo-opens-2026',
  summary = '2026년 10월 문을 연 삿포로 호텔의 객실, 식음 시설과 도심 접근성을 하얏트 발표로 확인합니다.',
  content = '## 삿포로 도심에 새 라이프스타일 호텔\n\n하얏트는 2026년 10월 3일 Hyatt Centric Sapporo를 공식 개장했다고 발표했습니다. 홋카이도 첫 Hyatt Centric으로, 객실과 스위트 216실은 모두 36㎡ 이상이라고 회사는 밝혔습니다.\n\n17층에는 홋카이도 식재료를 내세운 Matsu Grill & Bar가 들어섰으며, 오도리역과는 지하 보행로로 연결됩니다. 시설·규모는 호텔의 개장 발표 기준입니다.\n\n[자료: Hyatt Newsroom, 2026-10-03](https://newsroom.hyatt.com/2026_10_03_Hyatt_Centric_Sapporo_Officially_Opens)',
  author = '체크인데일리 편집팀',
  cover_image = 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80',
  status = 'published',
  published_at = '2026-10-03T03:00:00.000Z',
  updated_at = '2026-10-08T00:00:00.000Z'
WHERE id = 2;

UPDATE articles SET
  title = '교토 숙박세 2026년 3월 인상…최고 세율은 1만 엔',
  slug = 'kyoto-accommodation-tax-2026',
  summary = '교토 숙박세 개정으로 1인 1박 숙박료 구간별 세금이 달라집니다. 여행 예산에 반영할 기준을 정리했습니다.',
  content = '## 예약 금액만 보지 말고 숙박세도 확인하세요\n\n교토의 새 숙박세율은 2026년 3월 1일부터 적용됐습니다. 1인 1박 숙박료가 6,000엔 미만이면 200엔, 6,000~19,999엔이면 400엔이며, 숙박료 10만 엔 이상 구간의 세액은 1만 엔입니다.\n\n실제 세액은 숙박료 구간과 시의 산정 기준에 따라 달라질 수 있습니다. 예약 전 공식 안내와 숙소 결제 내역을 확인하세요.\n\n[자료: Kyoto City / Kyoto Travel](https://kyoto.travel/en/news/tax-change/) · [교토시 안내](https://www.city.kyoto.lg.jp/gyozai/cmsfiles/contents/0000236/236952/A4822.pdf)',
  author = '체크인데일리 편집팀',
  cover_image = 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=80',
  status = 'published',
  published_at = '2026-02-26T03:00:00.000Z',
  updated_at = '2026-10-08T00:00:00.000Z'
WHERE id = 5;

UPDATE articles SET
  title = '방한 외래객 1~8월 1,505만 명…전년 동기보다 21.6% 증가',
  slug = 'korea-inbound-visitors-2026-august',
  summary = '문체부의 2026년 1~8월 잠정 통계를 바탕으로 방한객과 관광 관련 카드 지출 흐름을 정리합니다.',
  content = '## 방한객 증가와 소비 지표를 따로 읽기\n\n문화체육관광부가 2026년 9월 28일 발표한 잠정치에 따르면 1~8월 방한 외래객은 15,048,435명으로 전년 동기보다 21.6% 증가했습니다. 8월 방문객은 약 225만 명으로 전년 동월 대비 23.3% 늘었습니다.\n\n같은 기간 관광 관련 카드 지출은 14조180억 원으로 48.5% 증가했습니다. 이 카드 지출 지표를 전체 여행객의 총지출과 동일하게 해석해서는 안 됩니다.\n\n[자료: 대한민국 문화체육관광부, 2026-09-28](https://www.mcst.go.kr/english/policy/pressView.jsp?pSeq=666)',
  category = 'realtime',
  author = '체크인데일리 편집팀',
  cover_image = 'https://images.unsplash.com/photo-1534274988757-a28bf1a57c17?auto=format&fit=crop&w=1200&q=80',
  status = 'published',
  published_at = '2026-09-28T03:00:00.000Z',
  updated_at = '2026-10-08T00:00:00.000Z'
WHERE id = 4;

INSERT INTO articles
  (title, slug, summary, content, category, author, cover_image, status, published_at, created_at, updated_at)
VALUES
  ('아시아·태평양 관광객 3억1,600만 명…2024년 33% 증가', 'asia-pacific-tourism-rebound-2024', 'UN Tourism 통계로 본 아시아·태평양 관광 회복과 2019년 대비 남은 격차.', '## 아시아·태평양 관광 회복\n\nUN Tourism은 2024년 이 지역의 국제 관광객을 3억1,600만 명으로 추산했습니다. 2023년보다 33%, 약 7,800만 명 늘어난 수치이며 2019년 대비 회복률은 87%였습니다.\n\n2023년 말 66%였던 회복률에서 상승했지만, 세계 평균 회복과는 여전히 차이가 있습니다. 수치는 2025년 1월 발표에 담긴 2024년 잠정 추산입니다.\n\n[자료: UN Tourism, 2025-01-20](https://www.untourism.int/news/international-tourism-recovers-pre-pandemic-levels-in-2024)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=80', 'published', '2025-01-20T03:00:00.000Z', '2025-01-20T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('일본 방일객 4,268만 명…2025년 연간 최고 기록', 'japan-inbound-record-2025', 'JNTO 연간 집계에서 방일 외객이 4,268만 명을 넘었습니다.', '## 일본 방문 수요, 연간 최고치\n\n일본정부관광국(JNTO)은 2025년 방일 외객을 42,683,600명으로 집계했습니다. 전년보다 15.8% 증가한 연간 최고치입니다.\n\n호주 방문객은 처음으로 연간 100만 명을 넘었고, 20개 시장에서 연간 누계 최고치를 기록했습니다. 집계는 JNTO의 2026년 1월 발표 기준입니다.\n\n[자료: JNTO, 2026-01-21](https://www.jnto.go.jp/news/press/20260121_monthly.html)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=80', 'published', '2026-01-21T03:00:00.000Z', '2026-01-21T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('IATA, 2025년 항공업계 순이익 360억 달러 전망', 'iata-airline-profit-outlook-2025', 'IATA가 2025년 6월 공개한 항공업계 전망이며 확정 실적이 아닙니다.', '## 전망과 확정 실적을 구분해야\n\nIATA는 2025년 6월 항공업계 순이익을 360억 달러, 순이익률을 3.7%로 전망했습니다. 당시 제시한 승객 1인당 순이익은 7.20달러였습니다.\n\n이는 발표 시점의 전망치입니다. 2025년 실제 실적으로 인용하지 않도록 기준 시점을 함께 표시합니다.\n\n[자료: IATA, 2025-06-02](https://www.iata.org/en/pressroom/2025-releases/2025-06-02-01/)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2025-06-02T03:00:00.000Z', '2025-06-02T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('지속가능항공유, 2025년 항공연료 수요의 0.7% 전망', 'iata-saf-production-outlook-2025', 'IATA 전망은 SAF 공급 확대와 가격 격차가 함께 남아 있음을 보여줍니다.', '## SAF 공급 확대의 과제\n\nIATA는 2025년 지속가능항공유(SAF) 생산량을 200만 톤으로 전망했습니다. 항공사 연료 사용량의 0.7%에 해당하며, 당시 글로벌 평균 비용은 기존 항공유의 4.2배로 추정됐습니다.\n\n모두 2025년 6월 발표 당시 전망치입니다. 실제 생산 실적과 구분해 읽어야 합니다.\n\n[자료: IATA, 2025-06-02](https://www.iata.org/en/pressroom/2025-releases/2025-06-02-01/)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1474302770737-173ee21bab63?auto=format&fit=crop&w=1200&q=80', 'published', '2025-06-02T03:00:00.000Z', '2025-06-02T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('항공기 인도 지연 전망…IATA, 2025년 인도량 1,692대 예상', 'iata-aircraft-delivery-outlook-2025', '공급망 문제로 항공기 인도 전망이 하향된 배경을 짚습니다.', '## 기단 확장 속도를 늦추는 공급 제약\n\nIATA는 2025년 항공기 인도량을 1,692대로 전망했습니다. 이는 1년 전 예상보다 약 26% 낮지만, 2018년 이후 가장 높은 수준이라고 당시 밝혔습니다.\n\n이는 실적 집계가 아니라 2025년 6월의 전망입니다. 항공사 기단 계획과 실제 인도량은 다를 수 있습니다.\n\n[자료: IATA, 2025-06-02](https://www.iata.org/en/pressroom/2025-releases/2025-06-02-01/)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2025-06-02T03:00:00.000Z', '2025-06-02T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('항공사 송금 제한 자금 12억 달러…IATA가 지목한 국제 연결성 위험', 'iata-blocked-airline-funds-2025', '2025년 10월 말 기준 제한 자금의 지역별 집중을 IATA 자료로 살핍니다.', '## 항공사 매출을 본국으로 보내기 어려운 시장\n\nIATA는 2025년 10월 말 기준 송금이 제한된 항공사 자금이 12억 달러라고 발표했습니다. 그중 93%가 아프리카와 중동에 집중됐고, 상위 10개 국가·지역이 전체의 89%를 차지했습니다.\n\n이는 2025년 기준 스냅샷이지 2026년 현재 잔액은 아닙니다. 외환·송금 제한이 항공 연결성에 미치는 영향을 다룬 자료입니다.\n\n[자료: IATA, 2025-12-10](https://www.iata.org/en/pressroom/2025-releases/2025-12-10-01/)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2025-12-10T03:00:00.000Z', '2025-12-10T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('2025년 세계 항공화물 수요 3.4% 증가…국제선은 4.2%', 'global-air-cargo-growth-2025', 'IATA의 연간 항공화물 수요·공급 집계와 2026년 전망을 분리해 소개합니다.', '## 항공화물 수요와 공급\n\nIATA에 따르면 2025년 세계 항공화물 수요(CTK)는 전년보다 3.4%, 국제선 수요는 4.2% 증가했습니다. 화물 공급(ACTK)은 3.7% 늘었습니다.\n\nIATA의 2026년 2.4% 수요 증가 수치는 전망이지 실적이 아닙니다. 발표일은 2026년 1월 29일입니다.\n\n[자료: IATA, 2026-01-29](https://www.iata.org/en/pressroom/2026-releases/2026-01-29-01/)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1474302770737-173ee21bab63?auto=format&fit=crop&w=1200&q=80', 'published', '2026-01-29T03:00:00.000Z', '2026-01-29T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('에어버스, 2025년 항공기 793대 인도…주문 잔량 8,754대', 'airbus-deliveries-backlog-2025', '에어버스의 2025년 인도 실적과 연말 주문 잔량을 회사 발표로 확인합니다.', '## 인도 실적과 주문 잔량\n\n에어버스는 2025년 91개 고객사에 상업용 항공기 793대를 인도했다고 발표했습니다. 총주문은 1,000대, 순주문은 889대였으며 연말 주문 잔량은 8,754대로 신기록을 세웠습니다.\n\n이는 제조사 실적 발표 기준입니다. 기종별 공급 상황은 항공사 운항 계획과 별도로 살펴볼 필요가 있습니다.\n\n[자료: Airbus, 2026-01-12](https://www.airbus.com/en/newsroom/press-releases/2026-01-airbus-reports-793-commercial-aircraft-deliveries-in-2025)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2026-01-12T03:00:00.000Z', '2026-01-12T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('IATA 전망: 2025년 실질 왕복 항공운임 374달러', 'iata-real-airfare-outlook-2025', '2014년과 비교한 실질 운임 전망과 기준 가격을 확인합니다.', '## 실질 운임 전망의 기준\n\nIATA는 2025년 실질 평균 왕복 운임을 2024년 달러 기준 374달러로 전망했습니다. 발표 자료는 이를 2014년보다 40% 낮은 수준으로 제시했습니다.\n\n2025년 여객 운임 수익률이 전년보다 4.0% 하락할 것이라는 수치도 당시 전망치입니다. 확정 평균 판매가로 오해하지 않도록 기준을 밝혔습니다.\n\n[자료: IATA, 2025-06-02](https://www.iata.org/en/pressroom/2025-releases/2025-06-02-01/)', 'major', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2025-06-02T03:00:00.000Z', '2025-06-02T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),

  ('에어아시아X, 쿠알라룸푸르-카라치 주 4회 노선 발표', 'airasia-x-kuala-lumpur-karachi-route', '회사가 발표한 신규 노선의 취항 예정일과 운항 빈도를 정리했습니다.', '## 말레이시아와 파키스탄 연결 계획\n\n에어아시아X는 쿠알라룸푸르-카라치 노선을 주 4회 운항하고 2025년 5월 30일 취항할 계획이라고 발표했습니다. 당시 회사는 네트워크가 22개 노선이며 해당 노선의 연간 탑승객을 10만 명 이상으로 전망했습니다.\n\n취항일과 탑승객 숫자는 발표 당시 계획·예측입니다. 현재 운항 여부와 시간표는 항공사에서 확인해야 합니다.\n\n[자료: AirAsia Newsroom, 2025-03-13](https://newsroom.airasia.com/news/airasia-x-continues-strong-growth-momentum-with-a-new-route-to-karachi-pakistans-largest-city)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2025-03-13T03:00:00.000Z', '2025-03-13T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('콴타스, 퍼스발 오클랜드·요하네스버그 노선 발표', 'qantas-perth-auckland-johannesburg-routes', '퍼스 국제선 확대 발표 당시 운항 시작 일정과 좌석 공급 전망을 확인합니다.', '## 퍼스의 국제선 선택지 확대 계획\n\n콴타스는 퍼스-오클랜드와 퍼스-요하네스버그 노선을 발표했습니다. 당시 첫 운항 예정일은 각각 2025년 12월 8일과 12월 7일이었고, 회사는 연간 15만5,000석 이상이 추가될 것으로 추산했습니다.\n\n일정과 좌석 수는 발표 당시 기준입니다. 실제 운항 현황은 항공사 최신 안내를 확인하세요.\n\n[자료: Qantas, 2025-05-06](https://www.qantasnewsroom.com.au/media-releases/qantas-takes-australians-further-announcing-two-new-international-routes-and-more-choice-for-customers)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=80', 'published', '2025-05-06T03:00:00.000Z', '2025-05-06T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('루프트한자 시티항공, 신규 제작 A320neo 첫 인도', 'lufthansa-city-airlines-first-a320neo', '180석 구성의 첫 A320neo와 당시 발표된 여름 노선 계획을 살펴봅니다.', '## 단거리 항공기 도입과 노선 확대\n\n루프트한자 시티항공은 2025년 4월 등록번호 D-AIJP인 신규 제작 A320neo를 인도받았다고 발표했습니다. 항공기는 180석 구성으로, 당시 회사는 A319 4대와 A320neo 4대를 운영 중이라고 밝혔습니다.\n\n바르셀로나와 파리 샤를드골 등 여름 목적지 추가 및 연말 기단 확대는 당시의 계획입니다.\n\n[자료: Lufthansa Group, 2025-04-09](https://newsroom.lufthansagroup.com/en/lufthansa-city-airlines-takes-delivery-of-its-first-all-new-airbus-a320neo/)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2025-04-09T03:00:00.000Z', '2025-04-09T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('델타항공, 대서양 횡단 노선 대부분에 무료 고속 Wi-Fi 확대', 'delta-free-wifi-transatlantic-routes', '델타의 국제선 연결 서비스 확대 발표와 향후 기단 계획을 구분해 정리합니다.', '## 국제선 기내 연결 확대\n\n델타항공은 유럽·이스라엘·서아프리카 노선 대부분에서 무료 Delta Sync Wi-Fi를 제공한다고 2025년 4월 발표했습니다. 남미 노선과 717 기단 개조 일정도 함께 안내했습니다.\n\n남미 확대와 기단 개조는 발표 당시 계획이므로 완료 여부는 현재 서비스 안내에서 확인해야 합니다.\n\n[자료: Delta News Hub, 2025-04-03](https://news.delta.com/keeping-you-connected-fast-free-wi-fi-now-most-transatlantic-routes-coming-regional-jets)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1529070538774-1843cb3265df?auto=format&fit=crop&w=1200&q=80', 'published', '2025-04-03T03:00:00.000Z', '2025-04-03T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('에미레이트항공, 보잉 777-9 65대 추가 주문 발표', 'emirates-orders-65-boeing-777x-2025', '두바이 에어쇼 당시 발표된 항공기·엔진 주문과 인도 예상 시점을 확인합니다.', '## 광동체 기재 주문 확대\n\n에미레이트항공은 2025년 두바이 에어쇼에서 보잉 777-9 65대를 추가 주문한다고 발표했습니다. 회사가 밝힌 정가 기준 주문액은 380억 달러이며 GE9X 엔진 130대도 함께 주문했습니다.\n\n첫 인도 예상 시점은 발표 당시 2027년 2분기였습니다. 이는 계약 발표 내용이며 실제 인도 일정은 변동될 수 있습니다.\n\n[자료: Emirates Media Centre, 2025-11-17](https://www.emirates.com/media-centre/emirates-orders-65-additional-boeing-777x-aircraft-worth-us-38-billion-at-dubai-airshow-2025/)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2025-11-17T03:00:00.000Z', '2025-11-17T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('에미레이트항공, A380·777 여객기 111대 객실 개조 계획', 'emirates-fleet-retrofit-111-aircraft', 'A380 60대와 777 51대의 객실 개조 계획 및 발표 당시 진행 상황을 정리했습니다.', '## 객실 개조 프로그램 다음 단계\n\n에미레이트항공은 A380 60대와 보잉 777 51대 등 총 111대의 다음 단계 객실 개조 계획을 발표했습니다. 회사는 2026년 8월부터 새 기내 제품과 개선된 Wi-Fi를 도입하겠다고 밝혔습니다.\n\n전체 프로그램은 당시 219대로 확대됐고 76대가 개조 완료됐다는 회사 집계입니다. 후속 완료 수치는 최신 발표에서 확인해야 합니다.\n\n[자료: Emirates Media Centre, 2025-11-18](https://www.emirates.com/media-centre/emirates-to-roll-out-next-phase-of-fleet-retrofit-programme-with-111-aircraft-set-for-next-level-enhancements/)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1529070538774-1843cb3265df?auto=format&fit=crop&w=1200&q=80', 'published', '2025-11-18T03:00:00.000Z', '2025-11-18T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('IATA: 2025년 세계 항공 여객수요 5.3% 증가', 'iata-passenger-demand-2025', '2025년 RPK, 좌석 공급과 탑승률 연간 수치를 IATA 집계로 확인합니다.', '## 여객 수요와 탑승률 모두 증가\n\nIATA의 2026년 1월 발표에 따르면 2025년 세계 여객 수요(RPK)는 전년보다 5.3% 증가했습니다. 공급(ASK)은 5.2% 늘었고 탑승률은 83.6%로 연간 최고치를 기록했습니다.\n\n국제선 수요는 7.1%, 국내선은 2.4% 증가했습니다. 수치는 IATA가 발표한 연간 통계입니다.\n\n[자료: IATA, 2026-01-29](https://www.iata.org/en/pressroom/2026-releases/2026-01-29-02/)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2026-01-29T03:00:00.000Z', '2026-01-29T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('IATA 집계: 2025년 항공화물 수요 3.4% 증가', 'iata-air-cargo-2025-results', '국제선 항공화물 수요와 12월 연간 비교 수치까지 요약했습니다.', '## 화물 수요의 연간 증가\n\nIATA는 2025년 세계 항공화물 수요가 전년보다 3.4%, 국제선은 4.2% 증가했다고 발표했습니다. 공급은 3.7% 늘었으며, 12월 세계 수요는 전년 동월보다 4.3% 증가했습니다.\n\n연간 수치는 2026년 1월 29일 발표 자료를 기준으로 했습니다.\n\n[자료: IATA, 2026-01-29](https://www.iata.org/en/pressroom/2026-releases/2026-01-29-01/)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1474302770737-173ee21bab63?auto=format&fit=crop&w=1200&q=80', 'published', '2026-01-29T03:00:00.000Z', '2026-01-29T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('에어버스, 2025년 고객사 91곳에 항공기 793대 인도', 'airbus-2025-delivery-results', '기종별 인도량과 주문 잔량을 포함한 에어버스 연말 실적 브리핑입니다.', '## A320 계열 인도가 전체의 중심\n\n에어버스의 2025년 상업용 항공기 인도량은 793대로 전년보다 4% 증가했습니다. A220 93대, A320 계열 607대, A330 36대, A350 57대가 인도됐습니다.\n\n연말 전체 주문 잔량은 8,754대, 광동체 주문 잔량은 1,124대로 회사가 발표한 연말 기록입니다.\n\n[자료: Airbus, 2026-01-12](https://www.airbus.com/en/newsroom/press-releases/2026-01-airbus-reports-793-commercial-aircraft-deliveries-in-2025)', 'airline', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2026-01-12T03:00:00.000Z', '2026-01-12T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),

  ('하얏트, 미국 Essentials 브랜드 포트폴리오 확대', 'hyatt-essentials-brand-expansion-2026', '하얏트의 장기 투숙·서비스 브랜드 확장 발표와 적용 방향을 소개합니다.', '## 체류 목적에 맞춘 브랜드 구성\n\n하얏트는 2026년 9월 미국 Essentials 포트폴리오에 Hyatt Place, Hyatt House, Hyatt Studios, Hyatt Select, Caption by Hyatt, Unscripted by Hyatt를 포함하는 확장 전략을 발표했습니다.\n\n회사는 지역 커뮤니티와 해안 지역, 업무·장기 체류 목적지의 선택지를 늘리는 방향을 소개했습니다. 개별 호텔의 개장 정보는 공식 예약 채널에서 확인하세요.\n\n[자료: Hyatt Newsroom, 2026-09-30](https://newsroom.hyatt.com/EssentialsGrowth2026)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-30T03:00:00.000Z', '2026-09-30T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('래디슨, 스톡홀름·코펜하겐 호텔 4곳을 넷제로 프로그램에 추가', 'radisson-verified-net-zero-hotels-2026', '북유럽 호텔의 Verified Net Zero 확대와 2030년 목표를 확인합니다.', '## 호텔 운영의 탄소 감축 프로그램\n\n래디슨 호텔 그룹은 2026년 9월 스톡홀름 3곳과 코펜하겐 1곳을 Verified Net Zero 프로그램에 추가했다고 발표했습니다. 북유럽과 영국 적용 호텔은 총 9곳이 됐다고 밝혔습니다.\n\n그룹은 2030년까지 인증 호텔 100곳을 목표로 제시했습니다. 이는 기업 발표 기준의 목표입니다.\n\n[자료: Radisson Hotel Group, 2026-09-30](https://www.radissonhotels.com/en-us/corporate/media/press-releases/Radisson-Hotel-Group-accelerates-ambition-for-100-Verified-Net-Zero-hotels-by-2030-with-four-new-hotels-in-Stockholm-and-Copenhagen)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-30T03:00:00.000Z', '2026-09-30T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('래디슨 글로벌 커리어 페스티벌, AI와 호텔업 경력 이동에 초점', 'radisson-career-festival-ai-hospitality', '2026년 10월 행사 프로그램에 담긴 호텔업의 AI·인재 개발 의제를 살펴봅니다.', '## 호텔업 인재 개발과 AI\n\n래디슨은 2026년 10월 한 달 동안 글로벌 Career Fest를 진행한다고 발표했습니다. 프로그램은 AI·미래 역량, 리더십 개발, 국제 이동, 직무 전환을 다룹니다.\n\n2025년 행사 등록 1만2,000건 이상과 소셜 도달 2,677만 회는 회사가 발표한 전년도 수치입니다.\n\n[자료: Radisson Hotel Group, 2026-09-17](https://www.radissonhotels.com/en-us/corporate/media/press-releases/Radisson-Hotel-Groups-global-career-festival-returns-with-a-focus-on-career-mobility-and-AI-in-hospitality)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-17T03:00:00.000Z', '2026-09-17T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('미 FTC 호텔 가격 규칙 시행…의무 수수료 포함 총액 표시', 'ftc-hotel-junk-fee-rule-2025', '미국 숙박요금 광고에서 필수 수수료를 포함한 총액 표시가 의무화됐습니다.', '## 필수 수수료를 포함한 가격 표시\n\n미국 연방거래위원회(FTC)의 규칙은 호텔·모텔·여관과 단기·휴가용 임대 숙박 가격 광고에 적용됩니다. 사업자는 의무 수수료를 포함한 총액을 명확하게 공개해야 합니다.\n\n최종 규칙은 2025년 5월 12일 시행됐습니다. 적용 범위와 세부 의무는 연방 관보의 최종 규칙을 확인하세요.\n\n[자료: Federal Register, 2025-01-10](https://www.federalregister.gov/documents/2025/01/10/2024-30293/trade-regulation-rule-on-unfair-or-deceptive-fees)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', 'published', '2025-01-10T03:00:00.000Z', '2025-01-10T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('런던 Waldorf Astoria, OSKIA 스파 파트너십 발표', 'waldorf-astoria-london-oskia-spa', '호텔 개장을 앞두고 공개된 스파 파트너와 예정 시설을 발표 기준으로 정리했습니다.', '## Admiralty Arch 호텔 스파 계획\n\nHilton은 Waldorf Astoria London Admiralty Arch와 OSKIA의 스파 파트너십을 2026년 10월 7일 발표했습니다. OSKIA는 스킨케어와 트리트먼트 파트너로, 호텔 전용 트리트먼트 컬렉션을 준비한다고 밝혔습니다.\n\n트리트먼트룸·사우나·스팀룸·하이드로테라피 풀은 발표 자료에 소개된 계획 시설입니다.\n\n[자료: Hilton Newsroom, 2026-10-07](https://stories.hilton.com/releases/waldorf-astoria-london-admiralty-arch-announces-oskia-as-spa-partner)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=80', 'published', '2026-10-07T03:00:00.000Z', '2026-10-07T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('힐튼, 벵갈루루 공항 권역에 600실 규모 호텔 2곳 개발', 'hilton-bengaluru-airport-hotels-2026', 'Conrad와 Hilton 브랜드 호텔의 개발 계획, 행사 공간과 개장 예상 시점입니다.', '## 공항 인근 복합 호텔 개발\n\nHilton은 Conrad Bengaluru Airport와 Hilton Bengaluru Airport 개발 계약을 발표했습니다. 두 호텔을 합해 600실 규모이며 인도 KIADB Hi-Tech Defence and Aerospace Park에 들어설 예정입니다.\n\n회사는 2030년 개장을 예상하고 7만2,000제곱피트 이상의 행사 공간을 계획한다고 밝혔습니다. 개장 일정과 설계는 변경될 수 있는 회사 계획입니다.\n\n[자료: Hilton Newsroom, 2026-10-06](https://stories.hilton.com/releases/conrad-bengaluru-airport-and-hilton-bengaluru-airport-signing)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', 'published', '2026-10-06T03:00:00.000Z', '2026-10-06T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('Hotel Indigo, 전 세계 운영 호텔 200곳 돌파', 'ihg-hotel-indigo-200-hotels-2026', 'IHG 라이프스타일 브랜드의 운영 규모와 2026년 중반 개발 파이프라인을 확인합니다.', '## 200개 운영 호텔과 개발 파이프라인\n\nIHG는 Hotel Indigo가 전 세계 운영 호텔 200곳에 도달했다고 2026년 10월 발표했습니다. 2019년 100곳에서 두 배가 됐으며, 30개국 이상에 진출했다고 밝혔습니다.\n\n2026년 6월 30일 기준 개발 파이프라인은 134개 호텔입니다. 운영 수와 파이프라인은 서로 다른 지표입니다.\n\n[자료: IHG, 2026-10-05](https://www.ihgplc.com/en/news-and-media/news-releases/2026/ihgs-hotel-indigo-reaches-200-open-hotels-worldwide)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=80', 'published', '2026-10-05T03:00:00.000Z', '2026-10-05T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('IHG, 중국권 호텔에서 콘서트 연계 숙박 서비스 확대', 'ihg-concert-focused-hospitality-2026', '공연 셔틀과 호텔 패키지 등 IHG가 소개한 공연 관람객 편의 서비스를 살펴봅니다.', '## 공연 관람과 호텔 투숙 연결\n\nIHG는 중국권 일부 호텔에서 공연장 이동 교통과 공연 일정에 맞춘 셔틀을 제공한다고 발표했습니다. HUALUXE Beijing Xinan은 조식·왕복 이동편 패키지를, InterContinental Hangzhou ICC는 늦은 체크아웃 등을 포함한 패키지를 소개했습니다.\n\n조건과 제공 여부는 호텔·공연별로 다를 수 있으므로 예약 전에 해당 숙소의 최신 안내를 확인해야 합니다.\n\n[자료: IHG, 2026-09-03](https://www.ihgplc.com/en/news-and-media/news-releases/2026/ihg-hotels-and-resorts-enhances-the-guest-journey-with-concert-focused-hospitality)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-03T03:00:00.000Z', '2026-09-03T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('Holiday Inn, 덴버 공항 인근 새 로비 디자인 호텔 개장', 'holiday-inn-denver-airport-new-lobby', '106실 호텔과 공항 셔틀 등 IHG가 공개한 새 건축 프로토타입을 소개합니다.', '## 새 Holiday Inn 로비 디자인\n\nIHG는 Holiday Inn & Suites Commerce City-Denver Airport를 새 로비 디자인을 적용한 첫 신축 프로토타입으로 소개했습니다. 호텔은 106실이며 덴버 국제공항에서 10분 이내 거리라고 회사는 안내했습니다.\n\n공항 셔틀·실내 온수 수영장·24시간 피트니스센터도 발표 자료에 기재됐습니다. 위치·운영 서비스는 예약 시 최신 안내를 확인하세요.\n\n[자료: IHG, 2026-08-27](https://www.ihgplc.com/en/news-and-media/news-releases/2026/holiday-inn-by-ihg-opens-first-new-build-featuring-reimagined-lobby-design-near-denver-airport)', 'hotel', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-27T03:00:00.000Z', '2026-08-27T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),

  ('하와이 숙박세 2026년 0.75%p 인상…기후 회복력 재원 마련', 'hawaii-green-fee-accommodation-tax', '하와이 Act 96의 시행 시점과 관광 관련 세금 변경 내용을 확인합니다.', '## 기후 대응 재원을 위한 관광 관련 부담\n\n하와이 주지사는 2025년 5월 SB 1396에 서명해 Act 96으로 제정했습니다. 법은 2026년부터 숙박세율을 0.75%포인트 인상하고, 주내 항구에 기항하는 크루즈선에도 해당 세금을 적용하도록 했습니다.\n\n여행자는 숙박 요금 외 세금과 적용 조건을 예약 전 확인해야 합니다. 정책 설명은 주지사실 발표 기준입니다.\n\n[자료: Hawaii Governor, 2025-05-27](https://governor.hawaii.gov/newsroom/office-of-the-governor-news-release-gov-green-signs-historic-senate-bill-1396-codifying-a-green-fee-to-mitigate-climate-impacts-in-hawaii/)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1200&q=80', 'published', '2025-05-27T03:00:00.000Z', '2025-05-27T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('베네치아 당일 방문객 부담금…2026년 지정일 제도와 면제 확인', 'venice-access-contribution-2026', '베네치아 공식 포털의 지정일 방문 부담금, 숙박객 면제와 사전 확인 사항입니다.', '## 베네치아 방문 전 공식 일정 확인\n\n베네치아의 접근 부담금은 매일 일률 적용이 아니라 공식 포털에 지정된 날짜에 당일 방문객을 대상으로 운영됐습니다. 숙박객 등 면제 대상은 별도 절차와 증명 요건을 확인해야 합니다.\n\n2026년 적용 일정은 종료됐습니다. 2027년 일정·요금은 아직 이 기사에서 확정적으로 안내하지 않으며, 여행 전에 공식 포털을 확인하세요.\n\n[자료: Comune di Venezia - Access Fee](https://cda.ve.it/en/)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1514890547357-a9ee288728e0?auto=format&fit=crop&w=1200&q=80', 'published', '2026-05-26T03:00:00.000Z', '2026-05-26T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('싱가포르 그랑프리 10월 9~11일 개최…마리나 베이 일정 확인', 'singapore-grand-prix-2026-dates', '2026 F1 공식 일정의 싱가포르 라운드 날짜와 개최지를 안내합니다.', '## 야간 도심 레이스 전 이동 계획\n\nFormula 1 공식 2026 일정에는 싱가포르 그랑프리가 10월 9일부터 11일까지 Marina Bay Street Circuit에서 열리는 것으로 기재돼 있습니다. 일정은 F1이 2025년 11월 발표한 2026 캘린더 기준입니다.\n\n세션별 시간, 교통 통제와 입장 안내는 일정 변경 가능성이 있으므로 주최자와 현지 교통기관 공지를 확인하세요.\n\n[자료: Formula 1 - 2026 calendar](https://www.formula1.com/en/racing/2026)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1200&q=80', 'published', '2025-11-17T03:00:00.000Z', '2025-11-17T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('홍콩 와인앤다인 페스티벌, 10월 22~25일 개최 예정', 'hong-kong-wine-dine-festival-2026', '홍콩관광청 행사 안내에 게시된 일정과 세부 운영정보 확인 방법입니다.', '## 가을 하버프런트 행사 일정\n\n홍콩관광청 행사 안내는 2026년 10월 22일부터 25일까지 Central Harbourfront에서 Wine & Dine Festival을 개최한다고 소개했습니다.\n\n행사 세부 시간·프로그램은 변경될 수 있습니다. 관광청 안내도 제3자 행사 정보의 변경 가능성을 고지하므로, 방문 전 주최 측 최신 공지를 확인하세요.\n\n[자료: Hong Kong Tourism Board - Events](https://www.discoverhongkong.com/eng/events.html)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 'published', '2026-10-07T03:00:00.000Z', '2026-10-07T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('선댄스 영화제, 2027년부터 콜로라도 볼더에서 개최', 'sundance-film-festival-boulder-2027', '2027년 영화제 일정과 개최지 이전 발표를 공식 자료로 확인합니다.', '## 유타에서 콜로라도로 개최지 이전\n\nSundance Institute는 2027년 영화제를 1월 21일부터 31일까지 콜로라도주 볼더에서 개최한다고 발표했습니다. 개최지 이전은 2026년 2월 24일 공식 발표에 담겼습니다.\n\n티켓 판매·교통·현장 운영 상황은 발표 이후 바뀔 수 있으므로 영화제 공식 안내에서 확인하세요.\n\n[자료: University of Colorado Boulder, 2026-02-24](https://www.colorado.edu/today/2026/02/24/sundance-film-festival-announces-dates-2027) · [Sundance Institute](https://festival.sundance.org/blogs/2027-sundance-film-festival)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80', 'published', '2026-02-24T03:00:00.000Z', '2026-02-24T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('뉴사우스웨일스 관광상 2026 결선 진출지 공개', 'nsw-tourism-awards-finalists-2026', '30개 부문 후보와 시드니 시상식 일정을 Destination NSW 발표로 정리했습니다.', '## NSW 관광 사업자와 명소 조명\n\nDestination NSW는 2026년 관광상 30개 부문 결선 진출자를 발표했습니다. 접수는 210건이었고 48개 사업자가 처음 참가했다고 밝혔습니다.\n\n시상식은 2026년 11월 9일 시드니 ICC에서 열릴 예정입니다. 후보 목록과 행사 일정은 주최 기관 발표 기준입니다.\n\n[자료: Destination NSW, 2026-10-06](https://www.destinationnsw.com.au/newsroom/2026-nsw-tourism-awards-finalists-announced)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1494783367193-149034c05e8f?auto=format&fit=crop&w=1200&q=80', 'published', '2026-10-06T03:00:00.000Z', '2026-10-06T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('필라델피아 가을 할로윈·유령 투어…행사별 운영일 확인', 'philadelphia-halloween-events-2026', 'Visit Philadelphia의 2026년 가을 행사 목록과 일정 확인 요령을 소개합니다.', '## 가을 행사 방문 전 개별 일정 점검\n\nVisit Philadelphia는 2026년 가을 유령 투어와 할로윈 명소, 계절 행사를 모아 안내하고 있습니다. 다만 통합 행사 목록은 개별 프로그램의 일정·티켓·연령 제한이 달라질 수 있습니다.\n\n방문 날짜를 정한 뒤 각 행사의 주최자 안내에서 운영일과 입장 조건을 다시 확인하세요.\n\n[자료: Visit Philadelphia - Events](https://www.visitphilly.com/events/)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-29T03:00:00.000Z', '2026-09-29T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('가이아나에서 카리브해 관광회의 SOTIC 2026 개최', 'guyana-hosts-caribbean-sotic-2026', '카리브해 관광기구의 2026년 회의 개최지와 공개 일정 정보를 소개합니다.', '## 카리브 관광 업계의 지역 회의\n\n카리브해 관광기구(CTO)의 SOTIC 2026은 가이아나에서 개최되는 것으로 행사 안내에 소개됐습니다. 개막일은 2026년 10월 6일로 보도·행사 정보에 나타납니다.\n\n이번 기사에서 종료일과 전체 프로그램은 확정 정보로 싣지 않습니다. 참가·방문 계획은 CTO의 갱신 공지에서 확인하세요.\n\n[자료: Caribbean Tourism Organization - SOTIC](https://www.onecaribbean.org/events/sotic/)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1200&q=80', 'published', '2026-10-06T03:00:00.000Z', '2026-10-06T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('카타르 2026~2027 관광 행사 캘린더…여행 전 공식 일정 확인', 'qatar-tourism-events-calendar-2026', 'Visit Qatar의 행사 캘린더를 여행 시기 계획에 활용하고 일정 변동을 확인하세요.', '## 행사 일정은 출발 전 다시 확인\n\nVisit Qatar는 스포츠·문화·엔터테인먼트 등 행사 일정을 공식 캘린더에서 안내합니다. 행사 페이지는 일정과 장소를 확인하는 출발점으로 활용할 수 있습니다.\n\n언론 보도에 나온 행사 총량은 동적으로 바뀌는 공식 캘린더에서 동일 수치로 검증하지 못해 확정 통계로 인용하지 않았습니다. 개별 행사의 최신 정보를 확인하세요.\n\n[자료: Visit Qatar - Events Calendar](https://visitqatar.com/intl-en/events-calendar)', 'destination', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-17T03:00:00.000Z', '2026-09-17T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),

  ('지방 공항·항만 입국 외래객 27.8%…대만·인도네시아 방한 증가', 'korea-regional-gateways-inbound-2026', '문체부 2026년 1~8월 자료에서 지방 관문 입국 비율과 주요 시장 변화를 살펴봅니다.', '## 수도권 밖 관문으로 들어오는 여행객\n\n문화체육관광부의 2026년 1~8월 자료에서 외래객 27.8%가 지방 공항·항만으로 입국했습니다. 대만인 방문객은 1,656,255명으로 32.2%, 인도네시아인은 295,279명으로 22.5% 증가했습니다.\n\n이는 입국 관문 통계이며 지방 숙박·관광 지출 비중과 같은 뜻은 아닙니다. 통계 기준은 2026년 9월 28일 발표 자료입니다.\n\n[자료: 대한민국 문화체육관광부, 2026-09-28](https://www.mcst.go.kr/english/policy/pressView.jsp?pSeq=666)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1534274988757-a28bf1a57c17?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-28T03:00:00.000Z', '2026-09-28T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('아일랜드 8월 방문객 2% 증가…숙박일·여행 지출은 감소', 'ireland-inbound-tourism-august-2026', '입국자 수와 체류 기간·소비가 다르게 움직인 아일랜드의 월간 통계입니다.', '## 방문객 증가가 지출 증가를 뜻하지는 않는다\n\n아일랜드 중앙통계청(CSO)은 2026년 8월 외국인 방문객이 788,700명으로 전년 동월보다 2% 증가했다고 발표했습니다. 반면 숙박일은 660만 박으로 2% 감소했고 평균 체류 기간은 8.6박에서 8.3박으로 줄었습니다.\n\n항공료를 제외한 방문객 지출은 7억2,900만 유로로 2% 감소했습니다. 수치는 2026년 9월 29일 발표된 월간 통계입니다.\n\n[자료: Ireland CSO, 2026-09-29](https://www.cso.ie/en/releasesandpublications/ep/p-ibt/inboundtourismaugust2026/)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-29T03:00:00.000Z', '2026-09-29T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('세계 국제 관광객 상반기 6억9,000만 명…2분기엔 감소', 'un-tourism-first-half-2026', 'UN Tourism 상반기 추정치와 분기별 흐름을 구분해 읽습니다.', '## 상반기 완만한 증가, 2분기 둔화\n\nUN Tourism은 2026년 상반기 국제 관광객을 약 6억9,000만 명으로 추산했습니다. 전년 동기보다 약 300만 명, 0.4% 증가한 수치입니다.\n\n증가율은 1분기 2%에서 2분기 1% 감소로 바뀌었고 6월 도착은 3% 감소했습니다. 이는 2026년 9월 17일 발표한 추정치이며 향후 개정될 수 있습니다.\n\n[자료: UN Tourism, 2026-09-17](https://www.untourism.int/news/international-tourism-holds-steady-with-04-growth-in-first-half-of-2026-as-middle-east-conflict-and-rising-costs-weigh-on-momentum)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-17T03:00:00.000Z', '2026-09-17T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('8월 세계 항공 여객수요 0.8% 감소…중동 제외 시 0.6% 증가', 'iata-passenger-demand-august-2026', 'IATA RPK·ASK·탑승률의 2026년 8월 월간 발표를 지역별로 살펴봅니다.', '## 지역별 차이를 보인 항공 여객 수요\n\nIATA는 2026년 8월 세계 여객 수요(RPK)가 전년 동월 대비 0.8% 감소했다고 발표했습니다. 중동 항공사를 제외하면 0.6% 증가했고, 중동 항공사 수요는 14.6% 감소했습니다.\n\n좌석 공급(ASK)은 0.3% 늘었고 탑승률은 85.1%로 0.9%포인트 낮았습니다. RPK는 여객 수와 이동거리를 반영하는 항공 수요 지표이지 단순 입국자 수가 아닙니다.\n\n[자료: IATA, 2026-09-30](https://www.iata.org/en/pressroom/2026-releases/09-30-air-passenger-demand-slips-august/)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', 'published', '2026-09-30T03:00:00.000Z', '2026-09-30T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('여행자 31%, 극한기상 우려로 여행 취소 경험…설문 결과', 'booking-climate-risk-travel-survey-2026', 'Booking.com 설문 응답과 플랫폼 검색 증가를 실제 관광객 수와 구분합니다.', '## 날씨 위험이 여행 시기 선택에 미치는 영향\n\nBooking.com은 2026년 4월 발표한 조사에서 응답자 74%가 목적지·시기를 정할 때 극한기상 위험을 고려하며, 31%는 우려로 여행을 취소한 적이 있다고 밝혔습니다. 42%는 성수기 외 여행을 계획했고 25%는 더 서늘한 목적지를 찾는다고 응답했습니다.\n\n플랫폼 숙소 검색 증가율도 함께 공개됐지만, 이는 실제 예약이나 방문객 증가 통계가 아닌 설문·검색 자료입니다.\n\n[자료: Booking.com, 2026-04-20](https://news.booking.com/bookingcom-research-reveals-how-climate-uncertainty-is-reshaping-peak-season-travel/)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1200&q=80', 'published', '2026-04-20T03:00:00.000Z', '2026-04-20T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('핼러윈 주말 숙소 검색 증가…에어비앤비 Z세대 검색 45%↑', 'airbnb-halloween-searches-2026', '에어비앤비 내부 검색 지표의 비교 기간과 예약 통계와의 차이를 설명합니다.', '## 핼러윈 여행 관심도 상승\n\n에어비앤비는 2026년 10월 6일 핼러윈 주말 숙소 검색이 전년보다 약 15%, Z세대 검색은 약 45% 증가했다고 밝혔습니다. 핼러윈 관련 위시리스트도 약 60% 늘었다고 발표했습니다.\n\n비교 기준은 2026년과 2025년 각 2분기의 핼러윈 주말 체크인 검색입니다. 플랫폼 검색 관심도는 예약이나 실제 방문 증가와 동일하지 않습니다.\n\n[자료: Airbnb Newsroom, 2026-10-06](https://news.airbnb.com/gen-z-is-driving-a-45-jump-in-halloween-weekend-searches)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 'published', '2026-10-06T03:00:00.000Z', '2026-10-06T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('월드컵 개최 도시에 에어비앤비 신규 숙소 15만 곳 이상', 'airbnb-world-cup-2026-host-city-results', 'Airbnb 자체 집계의 이용객·신규 숙소 규모와 적용 범위를 밝혔습니다.', '## 월드컵 기간 플랫폼 숙박 수요\n\nAirbnb는 2026년 월드컵 기간 16개 개최 도시의 자사 숙소에 196개국 출신 수백만 명이 체크인했다고 발표했습니다. 개최 도시에 신규 숙소가 15만 곳 이상 등록됐다고 밝혔습니다.\n\n평균 숙박 가격은 세금·수수료 포함 1박 250달러 미만이라는 회사 집계입니다. Airbnb 플랫폼 자료이며 개최 도시 전체 숙박 실적과는 다릅니다.\n\n[자료: Airbnb Newsroom, 2026-08-06](https://news.airbnb.com/record-airbnb-guest-numbers-host-earnings-at-fifa-world-cup-2026)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-06T03:00:00.000Z', '2026-08-06T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('미국 응답자 60%, 2026년 가을 주말여행 계획…Airbnb 조사', 'airbnb-fall-weekend-travel-survey-2026', '미국 성인 2,000명 설문 결과로, 전체 여행객 예약 통계와는 구분해야 합니다.', '## 가을 짧은 여행에 대한 설문\n\nAirbnb 의뢰 조사에서 미국 응답자 60%가 2026년 가을 주말여행을 계획한다고 답했습니다. 회사는 별도로 2025년 내부 예약 자료에서 가을 주말여행이 다른 계절보다 많았다고 소개했습니다.\n\n2026년 실제 주말 예약의 비중은 발표 자료에 수치로 제시되지 않았습니다. 설문은 미국 성인 2,000명 대상이며 전체 여행시장으로 일반화할 수 없습니다.\n\n[자료: Airbnb Newsroom, 2026-08-18](https://news.airbnb.com/fall-beats-summer-as-the-top-season-for-weekend-trips)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-18T03:00:00.000Z', '2026-08-18T03:00:00.000Z', '2026-10-08T00:00:00.000Z'),
  ('미국 성인 약 70%가 경기장 여행에 관심…Airbnb 설문', 'airbnb-groundhopping-survey-2026', '경기장·아레나 방문형 여행 관심을 조사한 미국 성인 설문 결과입니다.', '## 경기장 자체를 여행 목적지로\n\nAirbnb 의뢰 조사에서 응답자의 약 70%가 여러 경기장·아레나·공연장을 찾아다니는 이른바 그라운드호핑에 매력을 느낀다고 답했습니다. Focaldata가 2026년 7월 미국 성인 2,000명을 대상으로 온라인 설문을 실시했습니다.\n\n관심도 설문이지 실제 경기장 방문·숙박 예약 수치가 아니며 미국 표본을 전 세계 여행객에 일반화할 수 없습니다.\n\n[자료: Airbnb Newsroom, 2026-08-18](https://news.airbnb.com/fall-beats-summer-as-the-top-season-for-weekend-trips)', 'realtime', '체크인데일리 편집팀', 'https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-18T03:00:00.000Z', '2026-08-18T03:00:00.000Z', '2026-10-08T00:00:00.000Z');

